-- Isolated market staging, unverified INN source rows; do not merge with scientific-name cards.
-- Third-party extracted WHO INN source, preserved identifiers and original list references.
-- Source: https://github.com/fuarnos/drug-brand-crossref/blob/main/data/who_inn_names.csv
-- Source's stated license: CC BY-NC-SA 3.0 IGO. This table is private research staging, not publicly redistributed.
CREATE TABLE IF NOT EXISTS market_inn_staging (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 inn_number text NOT NULL,
 english_name text NOT NULL,
 series text NOT NULL,
 list_number text,
 latin_name text,
 source_url text,
 source_dataset text NOT NULL DEFAULT 'fuarnos/drug-brand-crossref/data/who_inn_names.csv',
 review_status text NOT NULL DEFAULT 'تحت المراجعة',
 arabic_name text,
 extraction_status text NOT NULL DEFAULT 'مستورد',
 imported_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(inn_number, source_dataset)
);
CREATE INDEX IF NOT EXISTS market_inn_staging_english_name_idx ON market_inn_staging(lower(english_name));

ON CONFLICT (inn_number,source_dataset) DO NOTHING;

ON CONFLICT (inn_number,source_dataset) DO NOTHING;

ON CONFLICT (inn_number,source_dataset) DO NOTHING;

ON CONFLICT (inn_number,source_dataset) DO NOTHING;

ON CONFLICT (inn_number,source_dataset) DO NOTHING;
